for v in proposal['variants']:
 assert Path(v['file']).name==v['file'] and v['file'].endswith('.py')
 s=(p/v['file']).read_text(); t=ast.parse(s); compile(t,v['file'],'exec')
 c=literal_config(t)
 assert c==v['config']
 m=methods(t)
 defaults={arg.arg:ast.literal_eval(default) for arg,default in zip(m['__init__'].args.args[-len(m['__init__'].args.defaults):],m['__init__'].args.defaults)}
 for k,val in c.items():assert k in defaults and val==defaults[k],(v['file'],k)
 assert set(c)==set(literal_config(ancestor)), 'Only values of existing architecture switches may change'
 assert {k for k in c if c[k]"'!=literal_config(ancestor)[k]}<={'"'match_action_content','residual_routing'}
