  old_assign=[dump(n) for n in old['_match_action_content'].body if isinstance(n,ast.Assign) and any(isinstance(a,ast.Name) and a.id==target for a in n.targets)]
  assert new_assign==old_assign
 assert dump(helper.body[-1])==dump(old['_match_action_content'].body[-1])
 print('PASS',v['file'],f'{len(m)-2} inherited methods exact; learned construction exact; CONFIG/defaults/source hash/imports/compile pass',sha)
assert len(set(normalized))==1
print('PASS four-cell AST identity modulo two declared selector defaults and CONFIG')
# All availability gates follow replacement in the unchanged method; verify their literal truth table.
select=old['_select_summary_alignment']
helper_line=next(n.lineno for n in ast.walk(select) if isinstance(n,ast.Call) and isinstance(n.func,ast.Attribute) and n.func.attr=='_match_action_content')
keep_assign=next(n for n in select.body if isinstance(n,ast.Assign) and any(isinstance(a,ast.Name) and a.id=='keep' for a in n.targets))
assert helper_line<keep_assign.lineno
availability=ast.literal_eval(keep_assign.value)
for mode,flags in {'observed':(False,)*5,**table}.items():
 for avail,gates in availability.items():
  for i in range(5):
   # Check information-source specification for all 80 row/mode/gate combinations.
   actual='zero' if not gates[i] else ('item' if flags[i] else 'action')
   if i in [1,2,3]:assert actual=='action'
   if avail=='none' and i in [0,4]:assert actual=='zero'
